import{af as a,z as i,J as t,ab as n}from"./chunks/framework.DOJTDj7A.js";const u=JSON.parse('{"title":"Billing","description":"","frontmatter":{},"headers":[],"relativePath":"terminology/billing.md","filePath":"terminology/billing.md"}'),l={name:"terminology/billing.md"};function o(h,e,s,d,r,c){return i(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792763086000"},[...e[0]||(e[0]=[n('<h1 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h1><p>All devices are individually billed on a monthly basis at the start of each month.</p><h2 id="payment-methods" tabindex="-1">Payment methods <a class="header-anchor" href="#payment-methods" aria-label="Permalink to &quot;Payment methods&quot;">​</a></h2><ul><li>Pre pay with auto bill: You pay for plans in advance of using them, and have billing details set up.</li><li>Pre pay: You pay for plans in advance of using them, but do not have billing details set up. If you do not correctly populate your plan pool, and control devices, devices may be deactivated.</li><li>Post pay: You pay for plans after using them, and have a billing account set up with us. This is typically used by businesses, and provides maximum flexibility, and an invoice at the end of each month. Only larger accounts are eligible for post pay, and you must contact us to set up a post pay account.</li></ul><h2 id="plan-pool" tabindex="-1">Plan pool <a class="header-anchor" href="#plan-pool" aria-label="Permalink to &quot;Plan pool&quot;">​</a></h2><p>All accounts have a pool of plan credits.</p><p>When devices are activated, or when the monthly billing cycle occurs, the device will consume plan credits from the pool of the owner of the device.</p><p>If no credits are available of the required type, one of the below options will occur:</p><ul><li>The plan will be purchased automatically, and added to the pool, if the account is pre pay and has billing details set up.</li><li>The plan will be automatically allocated, and billed in the next invoice, if the account is post pay and the device is on the post pay account.</li><li>The device will be deactivated, if the account is pre pay and has no billing details set up, and no remaining plan credits are available.</li></ul><p>This pool is shared between all devices on the account.</p><h3 id="bundled-plans" tabindex="-1">Bundled plans <a class="header-anchor" href="#bundled-plans" aria-label="Permalink to &quot;Bundled plans&quot;">​</a></h3><p>Some products, such as retail bundles, come with one or more plan credits bundled with the product.</p><p>When an order is placed, the plan credits will be added to the pool of the user that placed the order.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>Allocation of the plan credits will be done manually, and you may need to reach out to support to have the plan credits added to your account if they appear missing.</p></div><h3 id="bulk-purchasing" tabindex="-1">Bulk purchasing <a class="header-anchor" href="#bulk-purchasing" aria-label="Permalink to &quot;Bulk purchasing&quot;">​</a></h3><p>Plan credits can be purchased in bulk, at a discount via a <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">sales enquiry</a>.</p><p>Plans purchased this way will be added to the pool of the user that purchased the plans.</p><h2 id="initial-activation" tabindex="-1">Initial activation <a class="header-anchor" href="#initial-activation" aria-label="Permalink to &quot;Initial activation&quot;">​</a></h2><p>When a device is activated, it will consume a plan credit from the pool, or you will be prompted to purchase a plan credit.</p><ul><li>Pre Pay: If the activation happens during the billing cycle, a full month&#39;s plan will be consumed, and you&#39;ll be credited for the remaining days of the month in your next invoice.</li><li>Post Pay: A full plan will be allocated, and partially billed in the next invoice, based on the number of days used in the month (with a minimum spend also applied).</li></ul><h2 id="billing-cycle" tabindex="-1">Billing cycle <a class="header-anchor" href="#billing-cycle" aria-label="Permalink to &quot;Billing cycle&quot;">​</a></h2><p>The billing cycle is fixed to the start of each month.</p><ul><li>Pre Pay: <ul><li>Any plans purchased mid month will be allocated in full, and you will be credited for the remaining days or amount in the next billing invoice.</li><li>If credits are not used within an invoice, they will be shown, but applied in a future invoice.</li></ul></li></ul><h2 id="plan-changes" tabindex="-1">Plan changes <a class="header-anchor" href="#plan-changes" aria-label="Permalink to &quot;Plan changes&quot;">​</a></h2><p>Upgrades and downgrades of plans can be done at any time.</p><ul><li>Pre Pay: <ul><li>If you upgrade a plan, you will be credited for the remaining days of the month of your previous plan in the next invoice, and a plan will be consumed from the pool for the new plan, or purchased.</li><li>If you downgrade a plan, a plan will be consumed from the pool for the new plan, or purchased.</li><li>If you cancel a plan, you will not be credited for the remaining days of the month.</li></ul></li><li>Post Pay: <ul><li>If you upgrade, downgrade, or cancel a plan, you will be billed for the partial days used (with a minimum spend also applied) in the next invoice.</li></ul></li></ul><h2 id="calculations" tabindex="-1">Calculations <a class="header-anchor" href="#calculations" aria-label="Permalink to &quot;Calculations&quot;">​</a></h2><h3 id="pre-pay" tabindex="-1">Pre Pay <a class="header-anchor" href="#pre-pay" aria-label="Permalink to &quot;Pre Pay&quot;">​</a></h3><p>See <a href="#initial-activation">Initial activation</a> and <a href="#plan-changes">Plan changes</a> for how pre pay billing is calculated.</p><h3 id="post-pay" tabindex="-1">Post Pay <a class="header-anchor" href="#post-pay" aria-label="Permalink to &quot;Post Pay&quot;">​</a></h3><p>For post pay and other post pay billing, invoice line items are calculated from the individual plan allocations used during the billing month, then grouped by SKU on the invoice.</p><h4 id="how-the-quantity-is-calculated" tabindex="-1">How the quantity is calculated <a class="header-anchor" href="#how-the-quantity-is-calculated" aria-label="Permalink to &quot;How the quantity is calculated&quot;">​</a></h4><p>The quantity shown on a post pay invoice is the sum of the partial month usage for all allocations of that SKU during the billing month.</p><ul><li>Usage is prorated by the number of calendar days used in the billing month. (For example, April is divided by 30 days, while May is divided by 31 days)</li><li>Days are counted inclusively, so an allocation that starts and ends on the same calendar day still counts as 1 day of usage.</li></ul><p>For example, if a plan is active for 15 days in a 30 day month, it contributes 0.5 to the invoice quantity for that SKU.</p><h4 id="how-the-price-is-chosen" tabindex="-1">How the price is chosen <a class="header-anchor" href="#how-the-price-is-chosen" aria-label="Permalink to &quot;How the price is chosen&quot;">​</a></h4><p>For post pay plans, the unit price is selected from the default pricing bands, and any custom pricing bands that may be set up for the account.</p><p>This is based on the total quantity of that SKU used in the billing month, and the price bands that are set up for that SKU.</p><p>Once the correct price band has been selected, that unit price is applied to each SKU&#39;s prorated quantity on the invoice.</p><h4 id="why-the-same-device-can-appear-multiple-times" tabindex="-1">Why the same device can appear multiple times <a class="header-anchor" href="#why-the-same-device-can-appear-multiple-times" aria-label="Permalink to &quot;Why the same device can appear multiple times&quot;">​</a></h4><p>Billing is based on plan allocations, not only on unique devices.</p><p>This means a device can contribute multiple billed entries within the same month if it is:</p><ul><li>activated part way through the month</li><li>upgraded or downgraded</li><li>moved between plans more than once</li><li>deactivated and reactivated</li></ul><p>In these cases, each allocation records its own consumed and removed dates, and each contributes its own prorated amount to the monthly invoice.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="_1-pre-pay-one-renewing-one-new-device-no-billing" tabindex="-1">1. Pre Pay: One renewing, one new device, no billing <a class="header-anchor" href="#_1-pre-pay-one-renewing-one-new-device-no-billing" aria-label="Permalink to &quot;1. Pre Pay: One renewing, one new device, no billing&quot;">​</a></h3><p>Two devices renew at the end of the month, making use of a pool that has 4 plan credits for the unlimited plan, resulting in 2 plan credits being left, and no billing occurring.</p><p>Device A was activated the previous month and made use of a whole plan month this month. Device B was activated part way through the current month, and needs some credit applied to the invoice.</p><p>78% of device Bs plan was used (based on whole days of usage), leaving 22% of the plan to be credited back to the account.</p><p>Assuming a price of $13 for 1 month of the unlimited plan, the invoice was credited $2.86, which covers this 22%.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/sKw7mQ7.png" alt="" class="center" width="600" tabindex="0"><figcaption></figcaption></figure><h3 id="_2-post-pay" tabindex="-1">2. Post Pay <a class="header-anchor" href="#_2-post-pay" aria-label="Permalink to &quot;2. Post Pay&quot;">​</a></h3><p>A post pay account with 135 devices, with the following plan usage:</p><ul><li>6 devices using lite plans, which were activated for the whole month.</li><li>126 devices using standard plans, a few of which were activated part way through the month.</li><li>3 devices using unlimited plans, most of which were activated toward the end of the month.</li></ul><p>The invoice for the month would summarize this information, and show the total amount due for the month.</p><p>Any additional information about which plans were used by which devices, and when they were activated, is available in the plans section of the admin portal.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/aEESGKE.png" alt="" class="center" width="600" tabindex="0"><figcaption></figcaption></figure><h3 id="_3-post-pay-multiple-activation-periods" tabindex="-1">3. Post Pay: Multiple activation periods <a class="header-anchor" href="#_3-post-pay-multiple-activation-periods" aria-label="Permalink to &quot;3. Post Pay: Multiple activation periods&quot;">​</a></h3><p>A device is activated for 5 days, then deactivated for 10 days, then reactivated for 10 days in a 30 day month.</p><ul><li>Activation 1: On Day 1 of the month, a month plan is consumed by the device.</li><li>Deactivation: On Day 5 of the month, the device is deactivated, the same month plan is marked as removed.</li><li>Activation 2: On Day 15 of the month, a month plan is consumed by the device again (This is a new plan, and allocation, separate from the first activation).</li><li>Deactivation: On Day 25 of the month, the device is deactivated again, and the second month plan is marked as removed.</li></ul><p>This results in 15 days of usage, which contributes 0.5 to the invoice quantity for that SKU.</p><p>The invoice would show a quantity of 0.5 for that SKU, and the unit price would be selected based on the total quantity of that SKU used in the billing month, and the price bands that are set up for that SKU.</p>',62)])])}const m=a(l,[["render",o]]);export{u as __pageData,m as default};
